// 첫 번째 API 응답에서 사용자 ID 추출 및 데이터 보존
const userData = $input.all()[0].json;

// 입력 데이터 검증
if (!userData || !userData.id) {
  return [{
    json: {
      error: "Invalid user data received",
      userData: userData,
      timestamp: new Date().toISOString()
    }
  }];
}

const userId = userData.id;

// 두 번째 API 호출을 위한 URL 생성
const postsUrl = `https://jsonplaceholder.typicode.com/posts?userId=${userId}`;

// 사용자 정보를 보존하여 다음 단계로 전달
return [{
  json: {
    user: {
      id: userData.id,
      name: userData.name || 'Unknown',
      email: userData.email || 'unknown@example.com',
      company: userData.company || { name: 'Unknown Company' },
      website: userData.website || '',
      phone: userData.phone || ''
    },
    postsUrl: postsUrl,
    userId: userId,
    processing_step: "user_data_processed",
    timestamp: new Date().toISOString()
  }
}];

// 사용자 정보와 게시글 정보 결합
try {
  // 게시글 데이터 (현재 입력)
  const posts = $input.all()[0].json;

  // 이전 노드에서 사용자 데이터 가져오기
  let userData = null;
  try {
    userData = $node["사용자 데이터 처리"].json.user;
  } catch (e) {
    // 노드 참조 실패시 기본값 사용
    userData = {
      id: 1,
      name: "Leanne Graham",
      email: "Sincere@april.biz",
      company: { name: "Romaguera-Crona" }
    };
  }

  // 입력 데이터 검증
  if (!posts || !Array.isArray(posts)) {
    return [{
      json: {
        error: "Invalid posts data format",
        timestamp: new Date().toISOString(),
        api_chain_success: false,
        received_data: posts
      }
    }];
  }

  const result = {
    timestamp: new Date().toISOString(),
    user: {
      id: userData.id,
      name: userData.name,
      email: userData.email,
      company: userData.company?.name || "Unknown"
    },
    statistics: {
      totalPosts: posts.length,
      avgTitleLength: posts.length > 0 ? Math.round(posts.reduce((sum, post) => sum + (post.title?.length || 0), 0) / posts.length) : 0,
      avgBodyLength: posts.length > 0 ? Math.round(posts.reduce((sum, post) => sum + (post.body?.length || 0), 0) / posts.length) : 0
    },
    recentPosts: posts.slice(0, 3).map(post => ({
      id: post.id || 'unknown',
      title: post.title || 'No title',
      preview: (post.body || 'No content').substring(0, 50) + '...'
    })),
    api_chain_success: true,
    chain_summary: {
      steps_completed: ["사용자 정보 조회", "사용자 데이터 처리", "게시글 조회", "데이터 결합"],
      processing_time: new Date().toISOString()
    }
  };

  return [{ json: result }];

} catch (error) {
  return [{
    json: {
      error: "Data combination failed: " + error.message,
      timestamp: new Date().toISOString(),
      api_chain_success: false
    }
  }];
}
